package cn.trackcheck.beta;
import java.util.*;import java.io.*;import java.net.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import org.json.*;
public final class NativeRuntimeTest {
    private static int checks=0;private static void check(boolean condition,String label){checks++;if(!condition)throw new AssertionError(label);}
    private static final String BASE="https://webvpn.dlut.edu.cn/http-8081/test/service/mobile/extExercise/";
    static NativeApi.Session session(){return new NativeApi.Session(NativeApi.object("ruleUrl",BASE+"findExeRule","detailUrl",BASE+"findExtExercise","token","SIMULATED-TOKEN","userId","SIMULATED-USER","period","pmDel","origin","https://webvpn.dlut.edu.cn","referer","https://webvpn.dlut.edu.cn/http-8081/test/mobilenew/#/extExercise","userAgent","SIMULATED-UA"));}
    static class Fake extends HttpURLConnection {
        final ByteArrayOutputStream body=new ByteArrayOutputStream();final String response;final int code;boolean closed;
        Fake(String u,String response,int code)throws Exception{super(new URL(u));this.response=response;this.code=code;}
        public void connect(){}public void disconnect(){closed=true;}public boolean usingProxy(){return false;}public OutputStream getOutputStream(){return body;}public int getResponseCode(){return code;}public InputStream getInputStream(){return new ByteArrayInputStream(response.getBytes(StandardCharsets.UTF_8));}public Map<String,List<String>> getHeaderFields(){return Collections.singletonMap("Set-Cookie",Collections.singletonList("TEST=next"));}
    }
    static class Jar implements NativeApi.Cookies{String value="TEST=initial";public String get(String url){return value;}public void set(String url,String v){value=v;}}
    static String detail(String status){return NativeApi.object("status","PASS","pmDel",NativeApi.object("exercise_run_status",status,"distance","1000米","time","00时12分10秒","running_countdown_time",290,"tag_path",new JSONArray().put(NativeApi.object("reader_id","READER-PRIVATE","date_time","2026-09-28 19:17:30")))).toString();}
    public static void main(String[] args)throws Exception {
        List<String> lines=Files.readAllLines(Paths.get(args[0]),StandardCharsets.UTF_8);String scenario="";RunPolicy p=null;long epoch=1790400000000L;
        for(String line:lines){String[] v=line.split("\t",-1);if(!scenario.equals(v[0])){scenario=v[0];p=new RunPolicy();}long now=Long.parseLong(v[1]);RunPolicy.Input in=new RunPolicy.Input();in.status=v[2];in.runKey="same";
            if(!v[3].equals("-"))for(String event:v[3].split(";")){String[] e=event.split(",");in.cards.add(new RunPolicy.Card(e[0],e[1],e[2].equals("?")?null:epoch+Long.parseLong(e[2])));}
            RunPolicy.Motion m=new RunPolicy.Motion();if(!v[4].equals("-")){m.gpsMeters=Double.parseDouble(v[4]);m.gpsFresh=true;}m.stationary=Boolean.parseBoolean(v[5]);RunPolicy.Decision d=p.update(in,now,epoch+now,m);
            String[] actual={d.stage,d.type==null?"-":d.type,""+d.segments,""+d.laps,""+d.nextMs,d.seconds==null?"-":""+Math.round(d.seconds),""+d.stop};for(int i=0;i<actual.length;i++)if(!v[6+i].equals("*"))check(v[6+i].equals(actual[i]),scenario+" @"+now+" field "+i+" expected "+v[6+i]+" actual "+actual[i]);}
        JSONArray signatures=new JSONArray(new String(Files.readAllBytes(Paths.get(args[1])),StandardCharsets.UTF_8));for(int i=0;i<signatures.length();i++){JSONObject fixture=signatures.getJSONObject(i),fields=fixture.getJSONObject("fields");Map<String,String> values=new HashMap<>();for(String key:fields.keySet())values.put(key,fields.isNull(key)?null:fields.getString(key));check(RequestSigner.sign(values).equals(fixture.getString("sign")),"JS signing parity");}
        Jar jar=new Jar();List<Fake> calls=new ArrayList<>();NativeApi api=new NativeApi(session(),jar,url->{Fake f=new Fake(url,url.endsWith("findExeRule")?"{\"status\":\"PASS\",\"isRun\":\"1\",\"amId\":\"a\",\"pmId\":\"b\"}":detail("1"),200);calls.add(f);return f;});NativeApi.Result r=api.query();
        check(calls.size()==2,"two sequential read endpoints");check(calls.get(0).getRequestMethod().equals("POST"),"POST");check(!calls.get(0).getInstanceFollowRedirects(),"no login redirects");check(calls.get(1).getRequestProperty("Cookie").equals("TEST=next"),"cookie handoff");check(calls.get(1).getRequestProperty("Authorization").equals("SIMULATED-TOKEN"),"authorization retained only for request");check(calls.get(0).closed&&calls.get(1).closed,"connections close");
        JSONArray evidence=api.successfulAuthEvidence(r);check(evidence.length()==2,"rule and detail successful evidence");check(evidence.getJSONObject(0).getString("url").equals(calls.get(0).getURL().toString()),"evidence endpoint is actual request");check(evidence.getJSONObject(0).getString("digest").equals(RequestSigner.sha1("SIMULATED-TOKEN").toLowerCase(Locale.ROOT)),"evidence binds current token");check(Math.abs(System.currentTimeMillis()-evidence.getJSONObject(0).getLong("at"))<5000,"fresh evidence timestamp");check(!evidence.toString().contains("SIMULATED-TOKEN")&&!evidence.toString().contains("SIMULATED-USER"),"no raw credentials in bridge evidence");
        check(r.input.cards.size()==1&&r.input.cards.get(0).at!=null,"dated event parsed");check(r.safe.getJSONObject("sample").getInt("remaining")==290,"countdown preserved");check(!r.safe.toString().contains("SIMULATED")&&!r.safe.toString().contains("READER-PRIVATE"),"report excludes credentials and reader IDs");
        for(int code:new int[]{302,401,429,500}){NativeApi bad=new NativeApi(session(),jar,url->new Fake(url,"",code));try{bad.query();throw new AssertionError("HTTP accepted "+code);}catch(IOException e){check(e.getMessage().equals("HTTP_"+code),"HTTP error code");}}
        NativeApi cancelled=new NativeApi(session(),jar,url->{throw new AssertionError("cancelled request issued");});cancelled.cancel();try{cancelled.query();throw new AssertionError("cancel ignored");}catch(IOException e){check(e.getMessage().equals("CANCELLED"),"cancel before request");}
        NativeApi wait=new NativeApi(session(),jar,url->new Fake(url,"{\"status\":\"PASS\",\"isRun\":\"0\"}",200));check(!wait.query().input.hasSample,"rule-only wait");
        System.out.println("Native runtime: "+lines.size()+" JS-parity steps; "+checks+" assertions passed. No real HTTP, Android services or accounts used.");
    }
}
